static uint8_t de_plural_fn(int32_t num)
{
    UNUSED(num);
    uint32_t n = op_n(num); UNUSED(n);
    uint32_t i = op_i(n); UNUSED(i);
    uint32_t v = op_v(n); UNUSED(v);

    if ((i == 1 && v == 0)) return LV_I18N_PLURAL_TYPE_ONE;
    return LV_I18N_PLURAL_TYPE_OTHER;
}

static const lv_i18n_lang_t de_lang = {
    .locale_name = "de",
    .singulars = de_singulars,
    .singular_count = sizeof(de_singulars) / sizeof(de_singulars[0]) - 1,
    .plurals[LV_I18N_PLURAL_TYPE_ONE] = de_plurals_one,
    .plural_count[LV_I18N_PLURAL_TYPE_ONE] = sizeof(de_plurals_one) / sizeof(de_plurals_one[0]) - 1,
    .plurals[LV_I18N_PLURAL_TYPE_OTHER] = de_plurals_other,
    .plural_count[LV_I18N_PLURAL_TYPE_OTHER] = sizeof(de_plurals_other) / sizeof(de_plurals_other[0]) - 1,
    .locale_plural_fn = de_plural_fn
};

